package com.bank.dict;

import java.util.logging.Logger;

// Trie with wildcard '.' search for transaction references.
public class WordDictionary {

    private static final Logger log = Logger.getLogger(WordDictionary.class.getName());

    private final TrieNode root = new TrieNode();

    public void addWord(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            node = node.children.computeIfAbsent(c, k -> new TrieNode());
        }
        node.isWord = true;
        log.info("Added reference: " + word);
    }

    public boolean search(String pattern) {
        boolean found = dfs(pattern, 0, root);
        log.info("Search '" + pattern + "' -> " + found);
        return found;
    }

    private boolean dfs(String pattern, int i, TrieNode node) {
        if (i == pattern.length()) {
            return node.isWord;              // base: full pattern consumed
        }
        char c = pattern.charAt(i);
        if (c == '.') {                      // wildcard: try all children
            for (TrieNode child : node.children.values()) {
                if (dfs(pattern, i + 1, child)) return true;
            }
            return false;
        }
        TrieNode next = node.children.get(c); // normal: one exact child
        return next != null && dfs(pattern, i + 1, next);
    }
}
