package com.bank.dict;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DictionaryDemo {

    private static final Logger log = Logger.getLogger(DictionaryDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reference Lookup with Wildcards");
        WordDictionary dict = new WordDictionary();
        dict.addWord("TXN12");
        dict.addWord("TXN34");
        dict.addWord("TXN99");

        dict.search("TXN12");   // true  — exact
        dict.search("TXN.4");   // true  — matches TXN34
        dict.search("T.N99");   // true  — matches TXN99
        dict.search("TXN.0");   // false — no stored ref ends in 0 here
        dict.search(".....");   // true  — any 5-char stored ref
    }
}
